    pub trundle_e_push: Option<trundle_e::ForcedMovement>,
    #[serde(default)]
    pub vision_radius_modifiers: vision::RadiusModifiers,
    #[serde(skip)]
    pub path: VecDeque<Point>,
    #[serde(skip)]
    pub route: VecDeque<Point>,
    #[serde(skip)]
    pub home: Option<Point>,
    #[serde(skip)]
    pub camp: Option<u8>,
    #[serde(skip)]
    pub lane: Option<usize>,
    #[serde(skip)]
    pub next_ai: u64,
    #[serde(skip)]
    pub remove_at: Option<u64>,
}
